// Auto-generated from orders-dashboard.html -- served at GET /orders-dashboard-xk92q
export const ORDERS_DASHBOARD_HTML = "<title>OKFISH \u2014 objedn\u00e1vky sklad</title>\n<style>\n  :root {\n    --bg: #f5f5f5; --surface: #fff; --border: #e2e5e0;\n    --text: #1a1a1a; --text-dim: #55605a; --text-faint: #8a938c;\n    --brand: #88ba15; --brand-dark: #6d9611;\n    --ok: #1a7f37; --ok-dim: #e3f5ea; --ok-bar: #3fb95f;\n    --warn: #9a6700; --warn-dim: #fdf3d8; --warn-bar: #e0a72e;\n    --crit: #cf222e; --crit-dim: #fbe6e5; --crit-bar: #e6474f;\n  }\n  * { box-sizing: border-box; }\n  html, body { margin: 0; background: var(--bg); color: var(--text); font-family: ui-sans-serif, -apple-system, \"Segoe UI\", Roboto, sans-serif; }\n  .mono { font-family: ui-monospace, \"SF Mono\", Consolas, monospace; font-variant-numeric: tabular-nums; }\n\n  .topbar { background: linear-gradient(90deg, #ffffff 0%, var(--brand) 100%); padding: 14px 24px; display: flex; align-items: center; gap: 12px; }\n  .topbar img { height: 34px; display: block; }\n  .topbar .title { color: #1a2e00; font-weight: 700; font-size: 16px; letter-spacing: -0.01em; }\n  .topbar .title small { display: block; font-weight: 500; font-size: 12px; opacity: 0.9; }\n\n  .wrap { max-width: 1100px; margin: 0 auto; padding: 20px 24px 60px; }\n\n  /* -- S\u00fahrn hore: \u010do sa mus\u00ed rie\u0161i\u0165, jedn\u00fdm poh\u013eadom -- */\n  .summary-period { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-faint); font-weight: 650; margin-bottom: 6px; }\n  .summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 12px; }\n  .sum-card { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 8px 12px; }\n  .sum-card .num { font-size: 24px; font-weight: 700; line-height: 1; }\n  .sum-card .lbl { font-size: 12px; color: var(--text-faint); margin-top: 4px; }\n  .sum-card.red .num { color: var(--crit); }\n  .sum-card.yellow .num { color: var(--warn); }\n  .sum-card.green .num { color: var(--ok); }\n\n  .filters { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }\n  .filter-btn {\n    padding: 6px 13px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface);\n    font-size: 13px; font-weight: 600; cursor: pointer; color: var(--text-dim);\n  }\n  .filter-btn.active { background: var(--text); color: #fff; border-color: var(--text); }\n\n  .list { display: flex; flex-direction: column; gap: 6px; }\n\n  .list-header {\n    display: flex; align-items: center; gap: 10px; padding: 0 16px 8px;\n    font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-faint); font-weight: 650;\n  }\n  .lh-code { width: 90px; }\n  .lh-customer { width: 160px; }\n  .lh-date { width: 110px; }\n  .lh-spacer { flex: 1; }\n  .lh-status { width: 190px; }\n  .lh-summary { width: 140px; text-align: right; }\n  .lh-price { width: 100px; text-align: right; }\n\n  .order-row.is-resolved { opacity: 0.55; background: var(--bg) !important; border-color: var(--border) !important; }\n  .order-row.is-resolved .row-code, .order-row.is-resolved .row-customer { text-decoration: line-through; }\n  .resolve-badge {\n    background: var(--text); color: #fff; padding: 3px 10px; border-radius: 999px;\n    font-size: 11px; font-weight: 700; letter-spacing: 0.03em;\n  }\n  .resolve-toggle {\n    padding: 4px 9px; border-radius: 5px; border: 1px solid var(--text-faint); background: #fff; color: var(--text-dim);\n    font-size: 12.5px; font-weight: 650; cursor: pointer; white-space: nowrap;\n  }\n  .resolve-toggle:hover { background: var(--surface-2, #eee); }\n  .order-row {\n    background: var(--surface); border: 1px solid var(--border); border-left: 4px solid transparent;\n    border-radius: 8px; padding: 8px 12px;\n  }\n  .order-row.red { border-left-color: var(--crit-bar); background: var(--crit-dim); border-color: #f3bcbd; }\n  .order-row.yellow { border-left-color: var(--warn-bar); background: var(--warn-dim); border-color: #f0dca3; }\n  .order-row.green { border-left-color: var(--ok-bar); background: var(--ok-dim); border-color: #c3e8cf; }\n\n  .row-top { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }\n  .row-code { font-weight: 700; font-size: 14.5px; }\n  .row-customer { color: var(--text); font-weight: 700; font-size: 14.5px; text-transform: uppercase; }\n  .row-date { color: var(--text-faint); font-size: 11.5px; }\n  .row-spacer { flex: 1; }\n  .row-summary { font-size: 12px; font-weight: 700; color: #fff; padding: 3px 10px; border-radius: 999px; white-space: nowrap; }\n  .row-summary.red { background: var(--crit-bar); }\n  .row-summary.yellow { background: var(--warn-bar); }\n  .row-summary.green { background: var(--ok-bar); }\n  .row-price { font-weight: 650; }\n  .badge { padding: 2px 9px; border-radius: 5px; font-size: 11px; font-weight: 650; white-space: nowrap; }\n  .badge.paid { background: var(--ok-dim); color: var(--ok); }\n  .badge.unpaid { background: var(--crit-dim); color: var(--crit); }\n\n  .row-detail { margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border); }\n\n  .item-row { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; padding: 2px 0; font-size: 13px; flex-wrap: wrap; }\n  .item-name { color: var(--text-dim); flex: 1; }\n  .item-right { display: flex; align-items: baseline; gap: 10px; white-space: nowrap; }\n  .item-code { color: var(--text-faint); font-size: 11.5px; width: 60px; display: inline-block; text-align: right; }\n  .item-status { font-weight: 600; }\n  .item-status.missing { color: var(--crit); }\n  .item-status.unknown { color: var(--text-faint); }\n  .all-ok { color: var(--ok); font-size: 13px; font-weight: 600; }\n\n  .row-actions { display: flex; align-items: center; gap: 8px; margin-top: 10px; flex-wrap: wrap; }\n  .note-input {\n    flex: 1; min-width: 160px; font-family: inherit; font-size: 12.5px;\n    padding: 5px 8px; border-radius: 5px; border: 1px solid var(--border); background: #fff; color: var(--text);\n  }\n  .action-row { display: flex; gap: 8px; margin-bottom: 16px; justify-content: flex-end; }\n  .copy-all-codes {\n    padding: 7px 14px; border-radius: 6px; border: 1px solid var(--brand-dark); background: var(--brand);\n    color: #fff; font-size: 13px; font-weight: 600; cursor: pointer;\n  }\n  .copy-all-codes:hover { background: var(--brand-dark); }\n  .copy-all-codes.copied { background: var(--ok); border-color: var(--ok); }\n  .export-excel {\n    padding: 7px 14px; border-radius: 6px; border: 1px solid var(--brand-dark); background: var(--brand);\n    color: #fff; font-size: 13px; font-weight: 600; cursor: pointer; white-space: nowrap;\n  }\n  .export-excel:hover { background: var(--brand-dark); }\n\n  .copy-codes {\n    padding: 4px 9px; border-radius: 5px; border: 1px solid var(--crit); background: #fff; color: var(--crit);\n    font-size: 12.5px; font-weight: 650; cursor: pointer; white-space: nowrap;\n  }\n  .copy-codes:hover { background: var(--crit-dim); }\n  .copy-codes.copied { background: var(--ok-dim); border-color: var(--ok); color: var(--ok); }\n\n  .note-save, a.admin-link {\n    padding: 4px 9px; border-radius: 5px; border: none;\n    background: var(--brand); color: #fff; font-size: 12.5px; font-weight: 650; cursor: pointer; text-decoration: none; white-space: nowrap;\n  }\n  .note-save:hover, a.admin-link:hover { background: var(--brand-dark); }\n  .note-status { font-size: 12px; color: var(--text-faint); }\n\n  .empty-state { text-align: center; padding: 60px 20px; color: var(--text-faint); }\n  footer { text-align: center; font-size: 11.5px; color: var(--text-faint); margin-top: 26px; }\n</style>\n\n<div class=\"topbar\">\n  <img src=\"https://cdn.myshoptet.com/usr/www.okfish.sk/user/logos/logo-fish.png\" alt=\"OKFISH\">\n  <div class=\"title\">Objedn\u00e1vky \u2014 skladov\u00fd preh\u013ead<small>intern\u00fd n\u00e1stroj, nezdie\u013ea\u0165</small></div>\n</div>\n\n<div class=\"wrap\">\n  <div class=\"summary-period\">Preh\u013ead za posledn\u00fdch 14 dn\u00ed</div>\n  <div class=\"summary\" id=\"summary\"></div>\n  <div class=\"filters\" id=\"filters\"></div>\n  <div class=\"action-row\">\n    <button class=\"copy-all-codes\" id=\"copyAllCodes\">Kop\u00edrova\u0165 V\u0160ETKY ch\u00fdbaj\u00face k\u00f3dy (spo\u010d\u00edtan\u00e9 spolu)</button>\n    <button class=\"export-excel\" id=\"exportExcel\">\ud83d\udce5 Exportova\u0165 do Excelu (.csv)</button>\n  </div>\n  <div class=\"list-header\">\n    <span class=\"lh-code\">Objedn\u00e1vka</span>\n    <span class=\"lh-customer\">Z\u00e1kazn\u00edk</span>\n    <span class=\"lh-date\">D\u00e1tum</span>\n    <span class=\"lh-spacer\"></span>\n    <span class=\"lh-status\">Platba / sklad</span>\n    <span class=\"lh-price\">Cena</span>\n  </div>\n  <div id=\"content\"><div class=\"empty-state\">Na\u010d\u00edt\u00e1m\u2026</div></div>\n  <footer>Aktualizuje sa ka\u017ed\u00fdch 60 s</footer>\n</div>\n\n<script>\n  const params = new URLSearchParams(location.search);\n  const TOKEN = params.get('token') || '';\n  let currentFilter = 'all'; // 'all', 'action' (red+yellow), 'red', 'yellow', 'green'\n  let lastData = null;\n\n  function fmtMoney(v) {\n    return new Intl.NumberFormat('sk-SK', { style: 'currency', currency: 'EUR' }).format(Number(v) || 0);\n  }\n  function fmtDate(iso) {\n    if (!iso) return '';\n    const d = new Date(iso);\n    return d.toLocaleDateString('sk-SK') + ' ' + d.toLocaleTimeString('sk-SK', { hour: '2-digit', minute: '2-digit' });\n  }\n  function missingItems(o) {\n    return (o.items || []).filter(i => i.inStock === null || i.inStock < i.ordered);\n  }\n\n  function renderSummary(orders) {\n    const counts = { red: 0, yellow: 0, green: 0 };\n    let actionValue = 0;\n    orders.forEach(o => {\n      counts[o.semaphore]++;\n      if (o.semaphore !== 'green') actionValue += Number(o.priceWithVat) || 0;\n    });\n    const summary = document.getElementById('summary');\n    summary.innerHTML =\n      '<div class=\"sum-card red\"><div class=\"num mono\">' + counts.red + '</div><div class=\"lbl\">ni\u010d skladom</div></div>' +\n      '<div class=\"sum-card yellow\"><div class=\"num mono\">' + counts.yellow + '</div><div class=\"lbl\">nie\u010do ch\u00fdba</div></div>' +\n      '<div class=\"sum-card green\"><div class=\"num mono\">' + counts.green + '</div><div class=\"lbl\">v\u0161e skladom</div></div>' +\n      '<div class=\"sum-card\"><div class=\"num mono\">' + fmtMoney(actionValue) + '</div><div class=\"lbl\">s\u00fa\u010det cien objedn\u00e1vok, kde nie\u010do ch\u00fdba skladom</div></div>';\n  }\n\n  function renderFilters(orders) {\n    const counts = { red: 0, yellow: 0, green: 0, resolved: 0 };\n    orders.forEach(o => { counts[o.semaphore]++; if (o.resolved) counts.resolved++; });\n    const activeCount = orders.filter(o => !o.resolved).length;\n    const opts = [\n      ['all', 'Akt\u00edvne (' + activeCount + ')'],\n      ['red', 'Ni\u010d skladom (' + counts.red + ')'],\n      ['yellow', 'Nie\u010do ch\u00fdba (' + counts.yellow + ')'],\n      ['green', 'V\u0161e skladom (' + counts.green + ')'],\n      ['resolved', 'Vyrie\u0161en\u00e9 (' + counts.resolved + ')'],\n    ];\n    const filters = document.getElementById('filters');\n    filters.innerHTML = opts.map(([key, label]) =>\n      '<button class=\"filter-btn' + (currentFilter === key ? ' active' : '') + '\" data-filter=\"' + key + '\">' + label + '</button>'\n    ).join('');\n  }\n\n  function render(data) {\n    lastData = data;\n    const content = document.getElementById('content');\n    const draftNotes = {};\n    content.querySelectorAll('.note-input').forEach((el) => {\n      if (el.value) draftNotes[el.dataset.code] = el.value;\n    });\n\n    const orders = data.orders || [];\n    renderSummary(orders);\n    renderFilters(orders);\n\n    if (orders.length === 0) {\n      content.innerHTML = '<div class=\"empty-state\">\u017diadne otvoren\u00e9 objedn\u00e1vky za posledn\u00fdch 14 dn\u00ed.</div>';\n      return;\n    }\n\n    orders.sort((a, b) => new Date(b.creationTime).getTime() - new Date(a.creationTime).getTime());\n\n    const filtered = orders.filter(o => {\n      if (currentFilter === 'resolved') return !!o.resolved;\n      if (o.resolved) return false; // vyrie\u0161en\u00e9 sa mimo z\u00e1lo\u017eky \"Vyrie\u0161en\u00e9\" neukazuj\u00fa\n      if (currentFilter === 'all') return true;\n      return o.semaphore === currentFilter;\n    });\n\n    if (filtered.length === 0) {\n      content.innerHTML = '<div class=\"empty-state\">\u2713 Ni\u010d v tejto kateg\u00f3rii \u2014 dobr\u00e1 pr\u00e1ca!</div>';\n      return;\n    }\n\n    const rowSummaryLabel = { red: 'ni\u010d skladom', yellow: 'nie\u010do ch\u00fdba', green: 'PRIPRAVEN\u00c9 NA ODOSLANIE' };\n\n    let html = '<div class=\"list\">';\n    for (const o of filtered) {\n      const missing = missingItems(o);\n      html += '<div class=\"order-row ' + o.semaphore + (o.resolved ? ' is-resolved' : '') + '\" data-code=\"' + o.code + '\">';\n      html += '<div class=\"row-top\">';\n      html += '<span class=\"row-code mono\">' + o.code + '</span>';\n      html += '<span class=\"row-customer\">' + o.customerName + '</span>';\n      html += '<span class=\"row-date mono\">' + fmtDate(o.creationTime) + '</span>';\n      html += '<span class=\"row-spacer\"></span>';\n      if (o.resolved) html += '<span class=\"resolve-badge\">\u2713 VYRIE\u0160EN\u00c9</span>';\n      html += '<span class=\"badge ' + (o.paid ? 'paid' : 'unpaid') + '\">' + (o.paid ? 'Zaplaten\u00e9' : 'Nezaplaten\u00e9') + '</span>';\n      // \"Pripraven\u00e9 na odoslanie\" m\u00e1 zmysel len ke\u010f je aj zaplaten\u00e9 -- sklad OK\n      // ale nezaplaten\u00e1 objedn\u00e1vka (napr. zlyhan\u00e1 platba kartou) sa NEODOSIELA,\n      // bez oh\u013eadu na sklad. Potvrden\u00e9 \u017eivo: objedn\u00e1vka 2026000365 (Zlyhan\u00e1\n      // platba kartou) sa nespr\u00e1vne ukazovala ako \"pripraven\u00e9 na odoslanie\".\n      const summaryText = missing.length > 0\n        ? missing.length + '\u00d7 ' + rowSummaryLabel[o.semaphore]\n        : (o.semaphore === 'green' && !o.paid ? '\u2713 v\u0161e skladom (\u010dak\u00e1 na platbu)' : '\u2713 ' + rowSummaryLabel[o.semaphore]);\n      html += '<span class=\"row-summary ' + o.semaphore + '\">' + summaryText + '</span>';\n      html += '<span class=\"row-price mono\">' + fmtMoney(o.priceWithVat) + '</span>';\n      html += '</div>';\n\n      html += '<div class=\"row-detail\">';\n      if (missing.length === 0) {\n        html += '<div class=\"all-ok\">\u2713 v\u0161etko skladom, netreba ni\u010d objedn\u00e1va\u0165</div>';\n      } else {\n        for (const item of missing) {\n          const statusClass = item.inStock === null ? 'unknown' : 'missing';\n          let statusText;\n          if (item.inStock === null) {\n            statusText = 'nezn\u00e1my sklad';\n          } else {\n            const shortBy = item.ordered - item.inStock;\n            statusText = shortBy > 0 ? ('ch\u00fdba ' + shortBy + ' ks \u2014 treba objedna\u0165') : ('skladom len ' + item.inStock + ' ks');\n          }\n          const codeLabel = item.code ? '<span class=\"item-code mono\">[' + item.code + ']</span>' : '<span class=\"item-code\"></span>';\n          html += '<div class=\"item-row\"><span class=\"item-name\">' + item.name + '</span><span class=\"item-right\">' + codeLabel + '<span class=\"item-status ' + statusClass + '\">' + statusText + '</span></span></div>';\n        }\n      }\n      html += '<div class=\"row-actions\">';\n      if (missing.length > 0) {\n        const codesToCopy = missing.filter(i => i.code).map(i => {\n          const qty = i.inStock === null ? i.ordered : (i.ordered - i.inStock);\n          return i.code + ' x' + qty;\n        }).join(', ');\n        html += '<button class=\"copy-codes\" data-codes=\"' + codesToCopy + '\">Kop\u00edrova\u0165 ch\u00fdbaj\u00face k\u00f3dy</button>';\n      }\n      html += '<textarea class=\"note-input\" rows=\"1\" data-code=\"' + o.code + '\" placeholder=\"Pozn\u00e1mka e-shopu\u2026\"></textarea>';\n      html += '<button class=\"note-save\" data-code=\"' + o.code + '\">Ulo\u017ei\u0165 pozn\u00e1mku</button>';\n      html += '<span class=\"note-status\" data-code=\"' + o.code + '\"></span>';\n      html += '<button class=\"resolve-toggle\" data-code=\"' + o.code + '\" data-resolved=\"' + (o.resolved ? '1' : '0') + '\">' + (o.resolved ? '\u21ba Vr\u00e1ti\u0165 medzi akt\u00edvne' : '\u2713 Ozna\u010di\u0165 ako vyrie\u0161en\u00e9') + '</button>';\n      html += '<a class=\"admin-link\" href=\"' + o.adminUrl + '\" target=\"_blank\">Otvori\u0165 \u2192</a>';\n      html += '</div>';\n      html += '</div>'; // row-detail\n      html += '</div>'; // order-row\n    }\n    html += '</div>';\n    content.innerHTML = html;\n    content.querySelectorAll('.note-input').forEach((el) => {\n      if (draftNotes[el.dataset.code]) el.value = draftNotes[el.dataset.code];\n    });\n  }\n\n  function computeMissingTotals() {\n    // code -> { qty, name }, s\u010d\u00edtan\u00e9 naprie\u010d V\u0160ETK\u00ddMI otvoren\u00fdmi objedn\u00e1vkami\n    // (nez\u00e1le\u017e\u00ed na aktu\u00e1lnom filtri v zobrazen\u00ed).\n    const totals = {};\n    (lastData?.orders || []).forEach(o => {\n      missingItems(o).forEach(i => {\n        if (!i.code) return;\n        const qty = i.inStock === null ? i.ordered : (i.ordered - i.inStock);\n        if (!totals[i.code]) totals[i.code] = { qty: 0, name: i.name };\n        totals[i.code].qty += qty;\n      });\n    });\n    return totals;\n  }\n\n  document.getElementById('copyAllCodes').addEventListener('click', async (e) => {\n    if (!lastData) return;\n    const totals = computeMissingTotals();\n    const text = Object.entries(totals).map(([code, v]) => code + ' x' + v.qty).join(', ');\n    const btn = e.currentTarget;\n    try {\n      await navigator.clipboard.writeText(text);\n      const original = btn.textContent;\n      btn.textContent = '\u2713 Skop\u00edrovan\u00e9 (' + Object.keys(totals).length + ' k\u00f3dov)';\n      btn.classList.add('copied');\n      setTimeout(() => { btn.textContent = original; btn.classList.remove('copied'); }, 2200);\n    } catch (err) {\n      btn.textContent = 'chyba kop\u00edrovania';\n    }\n  });\n\n  document.getElementById('exportExcel').addEventListener('click', () => {\n    if (!lastData) return;\n    const totals = computeMissingTotals();\n    const rows = [['K\u00f3d', 'N\u00e1zov produktu', 'Po\u010det ks na objednanie']];\n    Object.entries(totals).forEach(([code, v]) => rows.push([code, v.name, v.qty]));\n\n    const csv = rows.map(row =>\n      row.map(cell => {\n        const s = String(cell);\n        return /[;\"\\n]/.test(s) ? '\"' + s.replace(/\"/g, '\"\"') + '\"' : s;\n      }).join(';')\n    ).join('\\r\\n');\n\n    // BOM pre spr\u00e1vnu diakritiku pri otvoren\u00ed v Exceli\n    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    const today = new Date().toISOString().slice(0, 10);\n    a.href = url;\n    a.download = 'okfish-chybajuce-produkty-' + today + '.csv';\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n    URL.revokeObjectURL(url);\n  });\n\n  document.getElementById('filters').addEventListener('click', (e) => {\n    const btn = e.target.closest('.filter-btn');\n    if (!btn) return;\n    currentFilter = btn.dataset.filter;\n    if (lastData) render(lastData);\n  });\n\n  document.getElementById('content').addEventListener('click', async (e) => {\n    if (e.target.classList.contains('copy-codes')) {\n      const codes = e.target.dataset.codes;\n      try {\n        await navigator.clipboard.writeText(codes);\n        const original = e.target.textContent;\n        e.target.textContent = '\u2713 Skop\u00edrovan\u00e9';\n        e.target.classList.add('copied');\n        setTimeout(() => { e.target.textContent = original; e.target.classList.remove('copied'); }, 1800);\n      } catch (err) {\n        e.target.textContent = 'chyba kop\u00edrovania';\n      }\n      return;\n    }\n\n    if (e.target.classList.contains('resolve-toggle')) {\n      const code = e.target.dataset.code;\n      const newResolved = e.target.dataset.resolved !== '1';\n      e.target.disabled = true;\n      try {\n        await fetch('/v1/order-resolved?token=' + encodeURIComponent(TOKEN), {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ code, resolved: newResolved }),\n        });\n        await poll(); // okam\u017eite prekresli\u0165 pod\u013ea nov\u00e9ho stavu\n      } catch (err) {\n        e.target.disabled = false;\n      }\n      return;\n    }\n\n    if (!e.target.classList.contains('note-save')) return;\n    const code = e.target.dataset.code;\n    const textarea = document.querySelector('.note-input[data-code=\"' + code + '\"]');\n    const status = document.querySelector('.note-status[data-code=\"' + code + '\"]');\n    const note = textarea.value;\n    e.target.disabled = true;\n    status.textContent = 'uklad\u00e1m\u2026';\n    try {\n      const res = await fetch('/v1/order-note?token=' + encodeURIComponent(TOKEN), {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ code, note }),\n      });\n      const data = await res.json();\n      status.textContent = res.ok ? '\u2713 ulo\u017een\u00e9' : ('chyba: ' + (data.error || res.status));\n    } catch (err) {\n      status.textContent = 'chyba spojenia';\n    }\n    e.target.disabled = false;\n  });\n\n  async function poll() {\n    try {\n      const res = await fetch('/v1/orders-status', { headers: { Authorization: 'Bearer ' + TOKEN }, cache: 'no-store' });\n      const data = await res.json();\n      render(data);\n    } catch (e) {\n      document.getElementById('content').innerHTML = '<div class=\"empty-state\">Chyba spojenia.</div>';\n    }\n  }\n\n  poll();\n  setInterval(poll, 60000);\n</script>\n";
